commands.command:
sudo tee /etc/nginx/sites-available/inventory-lb >/dev/null <<'EOF'
upstream inventory_backend {
    server 10.100.50.11:8080;
    server 10.100.50.12:8080;
}

server {
    listen 80 default_server;
    listen [::]:80 default_server;

    location / {
        proxy_pass http://inventory_backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}
EOF
sudo rm -f /etc/nginx/sites-enabled/default
sudo ln -sf /etc/nginx/sites-available/inventory-lb /etc/nginx/sites-enabled/inventory-lb
sudo nginx -t
sudo systemctl enable --now nginx
sudo systemctl reload nginx
sudo systemctl is-active nginx
